// Normalise le dossier reçu et ajoute un identifiant de traitement
const d = $input.first().json.body ?? $input.first().json;
return [{ json: {
  dossier_id: d.id ?? ('DOS-' + Date.now()),
  date_depot: d.date_depot ?? new Date().toISOString().slice(0, 10),
  declaration: d.declaration ?? '',
  formulaire: d.formulaire ?? {},
  constat: d.constat ?? null,
  facture: d.facture ?? null,
  photos: d.photos ?? [],
  audio: d.audio ?? null,
  journal: [{ etape: 'reception', ts: new Date().toISOString() }]
}}];

// Parse la sortie du LLM et distingue les erreurs fournisseur des réponses JSON invalides.
const dossier = $('Préparer le dossier').first().json;
const response = $input.first().json;
let intake = null, erreur = null;
if (response.error) {
  const status = response.error.status ? 'HTTP ' + response.error.status : 'requête refusée';
  erreur = 'Échec de l’appel Gemini (' + status + ') : ' + (response.error.message ?? 'détail indisponible');
} else {
  const raw = response.choices?.[0]?.message?.content;
  if (typeof raw !== 'string') {
    erreur = 'Réponse Gemini inattendue : choices[0].message.content est absent.';
  } else {
    try {
      intake = JSON.parse(raw.replace(/^```json|```$/g, '').trim());
    } catch (e) {
      erreur = 'JSON Intake invalide : ' + e.message;
    }
  }
}
return [{ json: { ...dossier, intake, erreurs: erreur ? [erreur] : [],
  journal: [...dossier.journal, { etape: 'intake', ok: !erreur, ts: new Date().toISOString() }] } }];
